engine.parseTemplate:
function parseTemplate(text) {
  text = String(text || "");
  var out = [];
  // ── Helpers (inlined) ─────────────────────────────────────────────
  function _lineOf(idx) {
    var n = 1;
    for (var i = 0; i < idx && i < text.length; i++) {
      if (text.charCodeAt(i) === 10) n++;
    }
    return n;
  }
  function _push(kind, m, extra) {
    var node = {
      kind:   kind,
      raw:    m[0],
      start:  m.index,
      end:    m.index + m[0].length,
      line:   _lineOf(m.index),
    };
    if (extra) {
      for (var k in extra) if (Object.prototype.hasOwnProperty.call(extra, k)) node[k] = extra[k];
    }
    out.push(node);
  }
  // ── {{ ... }} block — includes IF / ELSE / ENDIF / TITLE / DATE /
  //    DEF / |ask: directives. The lazy match prevents greedy gobbles
  //    across multiple blocks. ─────────────────────────────────────
  var reCurly = /\{\{([^}]+)\}\}/g;
  var mc;
  while ((mc = reCurly.exec(text)) !== null) {
    var inner = mc[1].trim();
    var upper = inner.toUpperCase();
    if (upper === "ELSE") { _push("else", mc); continue; }
    if (upper === "ENDIF" || upper === "END IF") { _push("endif", mc); continue; }
    if (/^IF\b/i.test(inner)) {
      _push("if", mc, { condition: inner.replace(/^IF\b\s*/i, "").trim() });
      continue;
    }
    if (upper === "TITLE") { _push("title", mc); continue; }
    if (upper === "DATE")  { _push("date", mc); continue; }
    // |ask: directive — embedded AI hint
    var askIdx = inner.indexOf("|ask:");
    if (askIdx === -1) askIdx = inner.indexOf("|ai:");
    if (askIdx !== -1) {
      var base = inner.slice(0, askIdx).trim();
      var askHint = inner.slice(askIdx + (inner.charAt(askIdx + 2) === "k" ? 5 : 4)).trim();
      _push("ask", mc, { name: base, askHint: askHint });
      continue;
    }
    // Format suffix split — name + :UPPER / :LOWER / :TITLE
    var fmt = "";
    var name = inner;
    var fmtMatch = inner.match(/^(.+):(UPPER|LOWER|TITLE)$/i);
    if (fmtMatch) { name = fmtMatch[1].trim(); fmt = fmtMatch[2].toUpperCase(); }
    _push("def", mc, { name: name, format: fmt });
  }
  // ── [[ ... ]] brackets — fill-in fields with optional |ask: hint ──
  var reSq = /\[\[([^\]]+)\]\]/g;
  var ms;
  while ((ms = reSq.exec(text)) !== null) {
    var inB = ms[1].trim();
    var askIdxB = inB.indexOf("|ask:");
    if (askIdxB === -1) askIdxB = inB.indexOf("|ai:");
    var nameB = inB, hintB = "";
    if (askIdxB !== -1) {
      nameB = inB.slice(0, askIdxB).trim();
      hintB = inB.slice(askIdxB + (inB.charAt(askIdxB + 2) === "k" ? 5 : 4)).trim();
    }
    var fmtB = "";
    var fmtMatchB = nameB.match(/^(.+):(UPPER|LOWER|TITLE)$/i);
    if (fmtMatchB) { nameB = fmtMatchB[1].trim(); fmtB = fmtMatchB[2].toUpperCase(); }
    _push("bracket", ms, { name: nameB, askHint: hintB, format: fmtB });
  }
  // ── $[ Amount ]  +  $![ Marker ] ──────────────────────────────────
  var reCur = /\$!?\[([^\]]+)\]/g;
  var mu;
  while ((mu = reCur.exec(text)) !== null) {
    var marker = mu[0].charAt(1) === "!";
    _push(marker ? "marker" : "currency", mu, { name: mu[1].trim() });
  }
  // Sort by position so consumers see them in doc order.
  out.sort(function (a, b) { return a.start - b.start; });
  return out;
}

// ─── lintTemplate — find syntax + logic issues in a template ────────
// Returns array of { severity, message, kind, line, start, end, suggest? }.
// severity: "error" | "warning" | "info".

engine.lintTemplate:
function lintTemplate(text) {
  text = String(text || "");
  var issues = [];
  // ── Helpers (inlined to keep this function self-contained) ──────
  function _lineOf(idx) {
    var n = 1;
    for (var i = 0; i < idx && i < text.length; i++) {
      if (text.charCodeAt(i) === 10) n++;
    }
    return n;
  }
  // ── 1. Unmatched {{ without }} ─────────────────────────────────
  var reOpenCurly = /\{\{/g; var oc;
  while ((oc = reOpenCurly.exec(text)) !== null) {
    var closeAt = text.indexOf("}}", oc.index + 2);
    var nextOpen = text.indexOf("{{", oc.index + 2);
    if (closeAt === -1 || (nextOpen !== -1 && nextOpen < closeAt)) {
      issues.push({
        severity: "error", kind: "unclosed_curly", line: _lineOf(oc.index),
        start: oc.index, end: oc.index + 2,
        message: "Unclosed {{ — missing }}",
        suggest: "Add }} after the placeholder name",
      });
    }
  }
  // ── 2. Unmatched [[ without ]] ─────────────────────────────────
  var reOpenSq = /\[\[/g; var os;
  while ((os = reOpenSq.exec(text)) !== null) {
    var closeAtS = text.indexOf("]]", os.index + 2);
    var nextOpenS = text.indexOf("[[", os.index + 2);
    if (closeAtS === -1 || (nextOpenS !== -1 && nextOpenS < closeAtS)) {
      issues.push({
        severity: "error", kind: "unclosed_bracket", line: _lineOf(os.index),
        start: os.index, end: os.index + 2,
        message: "Unclosed [[ — missing ]]",
        suggest: "Add ]] after the placeholder name",
      });
    }
  }
  // ── 3. IF / ELSE / ENDIF matching ──────────────────────────────
  var blocks = [];
  var reCurlyAll = /\{\{([^}]+)\}\}/g; var mc;
  while ((mc = reCurlyAll.exec(text)) !== null) {
    var u = mc[1].trim().toUpperCase();
    if (/^IF\b/i.test(mc[1])) blocks.push({ tag: "if",    pos: mc.index, end: mc.index + mc[0].length, raw: mc[0] });
    else if (u === "ELSE")    blocks.push({ tag: "else",  pos: mc.index, end: mc.index + mc[0].length, raw: mc[0] });
    else if (u === "ENDIF" || u === "END IF") blocks.push({ tag: "endif", pos: mc.index, end: mc.index + mc[0].length, raw: mc[0] });
  }
  // Walk the IF/ELSE/ENDIF tokens like a stack. Push IF, expect ELSE
  // and ENDIF in order. Stray ELSE / ENDIF outside any IF = error.
  var stack = [];
  for (var i = 0; i < blocks.length; i++) {
    var b = blocks[i];
    if (b.tag === "if") {
      stack.push({ ifPos: b.pos, ifRaw: b.raw, sawElse: false });
    } else if (b.tag === "else") {
      if (!stack.length) {
        issues.push({
          severity: "error", kind: "else_without_if", line: _lineOf(b.pos),
          start: b.pos, end: b.end,
          message: "{{ELSE}} outside any {{IF}} block",
          suggest: "Wrap with {{IF condition}} ... {{ELSE}} ... {{ENDIF}}",
        });
      } else {
        var top = stack[stack.length - 1];
        if (top.sawElse) {
          issues.push({
            severity: "error", kind: "duplicate_else", line: _lineOf(b.pos),
            start: b.pos, end: b.end,
            message: "Two {{ELSE}} blocks for one {{IF}}",
            suggest: "Only one {{ELSE}} per {{IF}}",
          });
        }
        top.sawElse = true;
      }
    } else if (b.tag === "endif") {
      if (!stack.length) {
        issues.push({
          severity: "error", kind: "endif_without_if", line: _lineOf(b.pos),
          start: b.pos, end: b.end,
          message: "{{ENDIF}} without matching {{IF}}",
          suggest: "Remove the {{ENDIF}} or add a matching {{IF condition}} earlier",
        });
      } else {
        stack.pop();
      }
    }
  }
  // Unclosed IFs left on the stack
  for (var j = 0; j < stack.length; j++) {
    var unclosed = stack[j];
    issues.push({
      severity: "error", kind: "if_without_endif", line: _lineOf(unclosed.ifPos),
      start: unclosed.ifPos, end: unclosed.ifPos + unclosed.ifRaw.length,
      message: unclosed.ifRaw + " never closed — no matching {{ENDIF}}",
      suggest: "Add {{ENDIF}} after the conditional content",
    });
  }
  // ── 4. Lone }} or ]] (closing without opening) ─────────────────
  var leftover = text.replace(/\{\{[^}]*\}\}/g, function (s) { return " ".repeat(s.length); });
  var loneClose = /\}\}/g; var lc;
  while ((lc = loneClose.exec(leftover)) !== null) {
    issues.push({
      severity: "warning", kind: "lone_close_curly", line: _lineOf(lc.index),
      start: lc.index, end: lc.index + 2,
      message: "Stray }} without matching {{",
      suggest: "Remove or pair with {{ earlier in the line",
    });
  }
  var leftover2 = text.replace(/\[\[[^\]]*\]\]/g, function (s) { return " ".repeat(s.length); });
  var loneCloseS = /\]\]/g; var lcs;
  while ((lcs = loneCloseS.exec(leftover2)) !== null) {
    issues.push({
      severity: "warning", kind: "lone_close_bracket", line: _lineOf(lcs.index),
      start: lcs.index, end: lcs.index + 2,
      message: "Stray ]] without matching [[",
      suggest: "Remove or pair with [[ earlier in the line",
    });
  }
  // ── 5. Empty placeholder body — {{}} or [[]] ─────────────────────
  var reEmptyCurly = /\{\{\s*\}\}/g; var ec;
  while ((ec = reEmptyCurly.exec(text)) !== null) {
    issues.push({
      severity: "warning", kind: "empty_curly", line: _lineOf(ec.index),
      start: ec.index, end: ec.index + 4,
      message: "Empty {{}} placeholder",
      suggest: "Either remove or fill in a variable name",
    });
  }
  var reEmptySq = /\[\[\s*\]\]/g; var es;
  while ((es = reEmptySq.exec(text)) !== null) {
    issues.push({
      severity: "warning", kind: "empty_bracket", line: _lineOf(es.index),
      start: es.index, end: es.index + 4,
      message: "Empty [[]] placeholder",
      suggest: "Either remove or fill in a field name",
    });
  }
  // ── 6. Invalid format suffix (only :UPPER / :LOWER / :TITLE legal) ─
  var reBadFmt = /\[\[[^\]]*:([A-Za-z]+)\]\]|\{\{[^}]*:([A-Za-z]+)\}\}/g; var bf;
  var legalFmts = { UPPER: 1, LOWER: 1, TITLE: 1 };
  while ((bf = reBadFmt.exec(text)) !== null) {
    var suffix = (bf[1] || bf[2] || "").toUpperCase();
    if (suffix && !legalFmts[suffix]) {
      issues.push({
        severity: "warning", kind: "bad_format_suffix", line: _lineOf(bf.index),
        start: bf.index, end: bf.index + bf[0].length,
        message: "Unknown format suffix :" + suffix + " (only :UPPER, :LOWER, :TITLE)",
        suggest: "Remove the suffix or use :UPPER / :LOWER / :TITLE",
      });
    }
  }
  // Sort by line, then position
  issues.sort(function (a, b) { return (a.line - b.line) || (a.start - b.start); });
  return issues;
}

// ─── fillTemplateSample — render template with sample values for preview ─
// Returns { text, fillCount, byKind: {def, bracket, currency, marker, if} }.
// sampleValues: map keyed by placeholder name; falls back to italicized
// placeholder name in <em> tags. ifPolicy: "include" | "exclude" — for
// {{IF}}/{{ELSE}}/{{ENDIF}}, "include" keeps the IF-block content,
// "exclude" keeps the ELSE-block content (default: "include").

engine.fillTemplateSample:
function fillTemplateSample(text, sampleValues, ifPolicy) {
  text = String(text || "");
  sampleValues = sampleValues || {};
  ifPolicy = ifPolicy || "include";
  var byKind = { def: 0, bracket: 0, currency: 0, marker: 0, "if": 0, "else": 0, endif: 0, title: 0, date: 0, ask: 0 };
  // ── First pass: collapse IF blocks per policy ──────────────────
  // Walk IF...ELSE...ENDIF. If policy==include, keep [if..else], drop [else..endif].
  // If policy==exclude, drop [if..else], keep [else..endif] (or drop entire if no else).
  // Naive: assumes IF/ENDIF are well-formed; if not, the linter would have
  // flagged it. We do a single greedy pass.
  function _stripIfBlocks(src) {
    var reIf    = /\{\{IF\b[^}]*\}\}/i;
    var reElse  = /\{\{ELSE\}\}/i;
    var reEndif = /\{\{(?:ENDIF|END IF)\}\}/i;
    var safety = 100; // bail-out on malformed input
    while (safety-- > 0) {
      var mIf = src.match(reIf);
      if (!mIf) break;
      byKind["if"]++;
      var ifStart = mIf.index;
      var ifEnd = ifStart + mIf[0].length;
      var rest = src.slice(ifEnd);
      var mEndif = rest.match(reEndif);
      if (!mEndif) {
        // unclosed — strip just the {{IF}} marker, leave content
        src = src.slice(0, ifStart) + src.slice(ifEnd);
        continue;
      }
      var endifStart = ifEnd + mEndif.index;
      var endifEnd = endifStart + mEndif[0].length;
      var mElse = src.slice(ifEnd, endifStart).match(reElse);
      var middle;
      if (mElse) {
        var elseStart = ifEnd + mElse.index;
        var elseEnd = elseStart + mElse[0].length;
        middle = (ifPolicy === "include")
          ? src.slice(ifEnd, elseStart)
          : src.slice(elseEnd, endifStart);
        byKind["else"]++;
      } else {
        middle = (ifPolicy === "include") ? src.slice(ifEnd, endifStart) : "";
      }
      byKind.endif++;
      src = src.slice(0, ifStart) + middle + src.slice(endifEnd);
    }
    return src;
  }
  text = _stripIfBlocks(text);
  // ── Second pass: replace all placeholders ─────────────────────
  // _fmt applies :UPPER/:LOWER/:TITLE suffix.
  function _fmt(val, suffix) {
    val = String(val == null ? "" : val);
    if (suffix === "UPPER") return val.toUpperCase();
    if (suffix === "LOWER") return val.toLowerCase();
    if (suffix === "TITLE") return val.replace(/\w\S*/g, function (w) {
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    });
    return val;
  }
  function _wrap(label) {
    // Italic-label fallback when no sample value supplied.
    return "<em style=\"color:#c9a227\">«" + label + "»</em>";
  }
  text = text.replace(/\{\{([^}]+)\}\}/g, function (full, inner) {
    inner = inner.trim();
    var upper = inner.toUpperCase();
    if (upper === "TITLE") { byKind.title++; return sampleValues["TITLE"] || _wrap("Title"); }
    if (upper === "DATE")  { byKind.date++;  return sampleValues["DATE"]  || _wrap(new Date().toLocaleDateString()); }
    // Format suffix split
    var fmt = "";
    var name = inner;
    var fmtMatch = inner.match(/^(.+):(UPPER|LOWER|TITLE)$/i);
    if (fmtMatch) { name = fmtMatch[1].trim(); fmt = fmtMatch[2].toUpperCase(); }
    // Strip |ask: hints
    var askIdx = name.indexOf("|ask:");
    if (askIdx === -1) askIdx = name.indexOf("|ai:");
    if (askIdx !== -1) name = name.slice(0, askIdx).trim();
    byKind.def++;
    if (sampleValues[name] != null) return _fmt(sampleValues[name], fmt);
    return _wrap(name + (fmt ? " :" + fmt : ""));
  });
  text = text.replace(/\[\[([^\]]+)\]\]/g, function (full, inner) {
    inner = inner.trim();
    var fmt = "";
    var name = inner;
    var fmtMatch = inner.match(/^(.+):(UPPER|LOWER|TITLE)$/i);
    if (fmtMatch) { name = fmtMatch[1].trim(); fmt = fmtMatch[2].toUpperCase(); }
    var askIdx = name.indexOf("|ask:");
    if (askIdx === -1) askIdx = name.indexOf("|ai:");
    if (askIdx !== -1) name = name.slice(0, askIdx).trim();
    byKind.bracket++;
    if (sampleValues[name] != null) return _fmt(sampleValues[name], fmt);
    return _wrap(name + (fmt ? " :" + fmt : ""));
  });
  text = text.replace(/\$(!?)\[([^\]]+)\]/g, function (full, marker, inner) {
    inner = inner.trim();
    if (marker) {
      byKind.marker++;
      return sampleValues["!" + inner] || _wrap("Marker: " + inner);
    }
    byKind.currency++;
    return sampleValues["$" + inner] || _wrap("$" + inner);
  });
  var fillCount = byKind.def + byKind.bracket + byKind.currency + byKind.marker;
  return { text: text, fillCount: fillCount, byKind: byKind };
}

// ─── classifyPlaceholder — given raw text, return its kind + parsed name ─
// Helper for the palette to recognize the cursor's surrounding placeholder.

engine.classifyPlaceholder:
function classifyPlaceholder(raw) {
  raw = String(raw || "").trim();
  if (!raw) return null;
  var m;
  if ((m = raw.match(/^\{\{(.+)\}\}$/))) {
    var inner = m[1].trim();
    var u = inner.toUpperCase();
    if (u === "ELSE") return { kind: "else", name: "" };
    if (u === "ENDIF" || u === "END IF") return { kind: "endif", name: "" };
    if (/^IF\b/i.test(inner)) return { kind: "if", name: inner };
    if (u === "TITLE") return { kind: "title", name: "TITLE" };
    if (u === "DATE")  return { kind: "date",  name: "DATE" };
    return { kind: "def", name: inner };
  }
  if ((m = raw.match(/^\[\[(.+)\]\]$/))) return { kind: "bracket", name: m[1].trim() };
  if ((m = raw.match(/^\$!\[(.+)\]$/))) return { kind: "marker", name: m[1].trim() };
  if ((m = raw.match(/^\$\[(.+)\]$/))) return { kind: "currency", name: m[1].trim() };
  return null;
}

view.renderTemplateEditorLanding:
function renderTemplateEditorLanding(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var templates = opts.templates || [];
  var onEditCurrent = opts.onEditCurrent || function () {};
  var onEditTemplate = opts.onEditTemplate || function () {};
  var onBack = opts.onBack || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_te_root";
  root.innerHTML =
    '<div class="_eli3_te_header">' +
      '<div class="_eli3_te_header_eyebrow">⚡ Template Editor · ALPHA</div>' +
      '<h1 class="_eli3_te_header_title">Author &amp; Edit Templates</h1>' +
      '<div class="_eli3_te_header_sub">Insert placeholders with one click. Lint your template as you type. Preview filled output instantly. Edit the current Word document, or pick from your library below.</div>' +
      '<div class="_eli3_te_header_actions">' +
        '<button class="_eli3_te_btn _eli3_te_btn_gold" data-act="edit-current">✎ Edit Current Document</button>' +
        '<button class="_eli3_te_btn _eli3_te_btn_ghost" data-act="back">← Back</button>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_te_body">' +
      '<div class="_eli3_te_section_label">' +
        '<span>Template Library</span>' +
        '<span class="_eli3_te_count_chip">' + templates.length + '</span>' +
      '</div>' +
      '<div data-zone="library"></div>' +
    '</div>';
  mount.appendChild(root);

  var libZone = root.querySelector('[data-zone="library"]');
  if (!templates.length) {
    libZone.innerHTML =
      '<div class="_eli3_te_empty">' +
        '<div class="_eli3_te_empty_icon">📑</div>' +
        '<div class="_eli3_te_empty_msg">No templates in your library yet. Click <strong>Edit Current Document</strong> to start editing the active Word doc — the editor works on whatever you have open.</div>' +
      '</div>';
  } else {
    templates.forEach(function (t) {
      var card = document.createElement("div");
      card.className = "_eli3_te_lib_card";
      var fileName = t.name || t.label || t.id || "(unnamed)";
      var meta = [];
      if (t.agreementType)  meta.push("📄 " + _esc(t.agreementType));
      if (t.version)        meta.push("v" + _esc(t.version));
      if (t.lastUpdated)    meta.push("Updated " + _esc(_fmtDate(t.lastUpdated)));
      card.innerHTML =
        '<div class="_eli3_te_lib_icon">📋</div>' +
        '<div class="_eli3_te_lib_main">' +
          '<div class="_eli3_te_lib_name">' + _esc(fileName) + '</div>' +
          (meta.length ? '<div class="_eli3_te_lib_meta">' + meta.join(' &middot; ') + '</div>' : '') +
        '</div>' +
        '<button class="_eli3_te_btn _eli3_te_btn_platinum" data-act="edit">✎ Edit</button>';
      card.querySelector('[data-act="edit"]').onclick = function () { onEditTemplate(t); };
      libZone.appendChild(card);
    });
  }
  root.querySelector('[data-act="edit-current"]').onclick = onEditCurrent;
  root.querySelector('[data-act="back"]').onclick = onBack;

  function _fmtDate(d) {
    try {
      var dt = (typeof d === "number") ? new Date(d) : new Date(String(d));
      return dt.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
    } catch (_) { return ""; }
  }
}

