      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return null;
  var templateName = opts.templateName || "Current Document";
  var onBack       = opts.onBack       || function () {};
  var onInsert     = opts.onInsert     || function () {};
  var onRefresh    = opts.onRefresh    || function () {};
  var onSave       = opts.onSave       || function () {};
  var onLintItemClick = opts.onLintItemClick || function () {};
  var onMetadataChange = opts.onMetadataChange || function () {};
  var currentMetadata = opts.metadata || {};

  var activeTab = "palette";

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_te_root";
  root.innerHTML =
    '<div class="_eli3_te_header">' +
