  var lintCountEl = root.querySelector('[data-lint-count]');

  function _switchTab(tab) {
    activeTab = tab;
    root.querySelectorAll("._eli3_te_tab").forEach(function (b) {
      if (b.getAttribute("data-tab") === tab) b.classList.add("_eli3_te_tab_active");
      else b.classList.remove("_eli3_te_tab_active");
    });
    _renderActiveTab();
  }
  function _renderActiveTab() {
    if (activeTab === "palette")      _renderPalette(bodyZone);
    else if (activeTab === "lint")    _renderLintList(bodyZone, handle._currentIssues || []);
    else if (activeTab === "preview") _renderPreviewPanel(bodyZone, handle._currentPreview);
    else if (activeTab === "meta")    _renderMetadataForm(bodyZone);
  }

  // ── Palette tab ─────────────────────────────────────────────────
  // Categorized buttons that call onInsert(snippet, label) when clicked.
  // Snippets include leading/trailing space hints where helpful so they
  // don't fuse with the user's surrounding text.
  function _renderPalette(zone) {
    var groups = [
      { label: "Variables (substituted at fill time)", items: [
        { snippet: "{{TITLE}}",         label: "TITLE — agreement title",         tip: "Inserts the file name / agreement title" },
        { snippet: "{{DATE}}",          label: "DATE — today",                    tip: "Inserts today's date at fill time" },
        { snippet: "{{Variable_Name}}", label: "{{Custom Variable}}",             tip: "Custom variable; user fills at Build Draft Step 1" },
      ]},
      { label: "Bracket Fields (user fills these)", items: [
        { snippet: "[[Party Name]]",     label: "[[Party Name]]",                 tip: "Standard fillable field" },
        { snippet: "[[Address]]",        label: "[[Address]]",                    tip: "Standard fillable field" },
        { snippet: "[[Effective Date]]", label: "[[Effective Date]]",             tip: "Standard fillable field" },
        { snippet: "[[Field Name]]",     label: "[[Custom Field]]",               tip: "Custom field; user fills at Build Draft Step 2" },
      ]},
      { label: "Conditional Logic (Step 1 questions)", items: [
        { snippet: "{{IF condition}}\n\n{{ENDIF}}",                   label: "{{IF ...}} ... {{ENDIF}}",       tip: "Show content only if condition is true at Step 1" },
        { snippet: "{{IF condition}}\n\n{{ELSE}}\n\n{{ENDIF}}",       label: "{{IF}} ... {{ELSE}} ... {{ENDIF}}", tip: "Branch content on a Step 1 answer" },
        { snippet: "{{ELSE}}",                                        label: "{{ELSE}}",                       tip: "Else branch (only inside IF/ENDIF)" },
        { snippet: "{{ENDIF}}",                                       label: "{{ENDIF}}",                      tip: "Close an IF block" },
      ]},
      { label: "Currency &amp; Markers", items: [
        { snippet: "$[Amount]",  label: "$[Amount]",  tip: "Currency field — auto-formatted at fill" },
        { snippet: "$![Marker]", label: "$![Marker]", tip: "Highlighted marker for review tools (legal_risks, error_review)" },
      ]},
      { label: "AI Fill Hint (Build Draft Step 2 helper)", items: [
        { snippet: "[[Field Name|ask: short description for the AI]]",   label: "[[Field|ask: hint]]",   tip: "Adds an AI-fill hint to a bracket field" },
        { snippet: "{{Variable_Name|ask: short description for the AI}}", label: "{{Variable|ask: hint}}", tip: "Adds an AI-fill hint to a variable" },
      ]},
      { label: "Format Suffixes (case transforms)", items: [
        { snippet: "[[Field Name:UPPER]]", label: ":UPPER suffix", tip: "Force value uppercase at fill" },
        { snippet: "[[Field Name:LOWER]]", label: ":LOWER suffix", tip: "Force value lowercase at fill" },
        { snippet: "[[Field Name:TITLE]]", label: ":TITLE suffix", tip: "Force value Title Case at fill" },
      ]},
    ];
    var html = '<div class="_eli3_te_palette_intro">Click any button to insert at the current Word cursor position.</div>';
    groups.forEach(function (g) {
      html += '<div class="_eli3_te_palette_group">';
      html += '<div class="_eli3_te_palette_group_lbl">' + _esc(g.label) + '</div>';
      g.items.forEach(function (it) {
        html += '<button class="_eli3_te_palette_btn" data-snippet="' + _esc(it.snippet) + '" title="' + _esc(it.tip) + '">';
        html += '<span class="_eli3_te_palette_btn_lbl">' + _esc(it.label) + '</span>';
        html += '<span class="_eli3_te_palette_btn_arrow">→</span>';
        html += '</button>';
      });
      html += '</div>';
    });
    zone.innerHTML = html;
    zone.querySelectorAll("._eli3_te_palette_btn").forEach(function (btn) {
      btn.onclick = function () {
        var snippet = btn.getAttribute("data-snippet");
        var label   = btn.querySelector("._eli3_te_palette_btn_lbl");
        onInsert(snippet, label ? label.textContent : "");
      };
    });
  }

  // ── Lint tab ────────────────────────────────────────────────────
  function _renderLintList(zone, issues) {
    if (!issues || !issues.length) {
      zone.innerHTML =
        '<div class="_eli3_te_empty">' +
          '<div class="_eli3_te_empty_icon">✅</div>' +
          '<div class="_eli3_te_empty_msg">No issues found. Re-scan after editing to catch new ones.</div>' +
        '</div>';
      return;
    }
    var html = '<div class="_eli3_te_palette_intro">Click any issue to locate it in the document.</div>';
    issues.forEach(function (iss, i) {
      var sev = iss.severity || "warning";
      var icon = sev === "error" ? "⛔" : (sev === "warning" ? "⚠" : "ℹ");
      html += '<div class="_eli3_te_lint_item _eli3_te_lint_' + _esc(sev) + '" data-idx="' + i + '">';
      html += '<div class="_eli3_te_lint_icon">' + icon + '</div>';
      html += '<div class="_eli3_te_lint_body">';
      html += '<div class="_eli3_te_lint_msg">' + _esc(iss.message || "Issue") + '</div>';
      if (iss.suggest) html += '<div class="_eli3_te_lint_sug">→ ' + _esc(iss.suggest) + '</div>';
      html += '<div class="_eli3_te_lint_meta">Line ' + _esc(iss.line) + ' &middot; ' + _esc(iss.kind || "syntax") + '</div>';
      html += '</div>';
      html += '</div>';
    });
    zone.innerHTML = html;
    zone.querySelectorAll("._eli3_te_lint_item").forEach(function (el) {
      el.onclick = function () {
        var idx = parseInt(el.getAttribute("data-idx"), 10);
        onLintItemClick(issues[idx]);
      };
    });
  }

  // ── Preview tab ─────────────────────────────────────────────────
  function _renderPreviewPanel(zone, preview) {
    if (!preview) {
      zone.innerHTML =
        '<div class="_eli3_te_empty">' +
          '<div class="_eli3_te_empty_icon">👁</div>' +
          '<div class="_eli3_te_empty_msg">Click <strong>↻ Re-scan</strong> at the top to refresh the preview from the current document.</div>' +
        '</div>';
      return;
    }
    var html = '<div class="_eli3_te_palette_intro">Sample-filled preview. Italic gold = no sample value supplied for this placeholder.</div>';
    html += '<div class="_eli3_te_preview_stats">';
    html += '<span><strong>' + _esc(preview.fillCount) + '</strong> placeholders</span>';
    if (preview.byKind && preview.byKind.def)      html += '<span>' + _esc(preview.byKind.def)      + ' variables</span>';
    if (preview.byKind && preview.byKind.bracket)  html += '<span>' + _esc(preview.byKind.bracket)  + ' brackets</span>';
    if (preview.byKind && preview.byKind["if"])    html += '<span>' + _esc(preview.byKind["if"])    + ' IF blocks</span>';
    if (preview.byKind && preview.byKind.currency) html += '<span>' + _esc(preview.byKind.currency) + ' currency</span>';
    html += '</div>';
    html += '<div class="_eli3_te_preview_doc">' + _preserveWhitespace(preview.text) + '</div>';
    zone.innerHTML = html;
  }
  function _preserveWhitespace(html) {
    // Preview output may contain <em> tags from the engine — keep those,
    // but convert raw newlines to <br> + preserve runs of spaces.
    return String(html || "")
      .replace(/\n\n+/g, "</p><p>")
      .replace(/\n/g, "<br>")
      .replace(/ {2,}/g, function (s) { return "&nbsp;".repeat(s.length); })
      .replace(/^/, "<p>")
      .replace(/$/, "</p>");
  }

  // ── Metadata tab ────────────────────────────────────────────────
  function _renderMetadataForm(zone) {
    var meta = currentMetadata || {};
    zone.innerHTML =
      '<div class="_eli3_te_palette_intro">Template metadata. Saved to your local template library. Use Admin Library Publisher to push to the CDN.</div>' +
      _field("Name", "input", "name", meta.name || "") +
      _field("Agreement Type", "input", "agreementType", meta.agreementType || "") +
      _field("Version", "input", "version", meta.version || "1.0") +
      _field("Description", "textarea", "description", meta.description || "") +
      _field("Tags (comma-separated)", "input", "tags", Array.isArray(meta.tags) ? meta.tags.join(", ") : (meta.tags || "")) +
      _field("Audience (comma-separated emails, empty = all)", "input", "audienceEmails", Array.isArray(meta.audienceEmails) ? meta.audienceEmails.join(", ") : (meta.audienceEmails || ""));
    zone.querySelectorAll("[data-meta-field]").forEach(function (el) {
      el.oninput = function () {
        var key = el.getAttribute("data-meta-field");
        var val = el.value;
        if (key === "tags" || key === "audienceEmails") {
          val = val.split(",").map(function (t) { return t.trim(); }).filter(Boolean);
        }
        currentMetadata[key] = val;
        onMetadataChange(currentMetadata);
      };
    });
  }
  function _field(label, type, key, val) {
    var ctl;
    if (type === "textarea") {
      ctl = '<textarea class="_eli3_te_input" data-meta-field="' + key + '" rows="3">' + _esc(val || "") + '</textarea>';
    } else {
      ctl = '<input class="_eli3_te_input" data-meta-field="' + key + '" value="' + _esc(val || "") + '" />';
    }
    return '<label class="_eli3_te_input_lbl">' + _esc(label) + '</label>' + ctl + '<div style="height:10px"></div>';
  }

  // ── Header buttons + tab clicks ─────────────────────────────────
  root.querySelectorAll("._eli3_te_tab").forEach(function (tab) {
    tab.onclick = function () { _switchTab(tab.getAttribute("data-tab")); };
  });
  root.querySelector('[data-act="back"]').onclick = onBack;
  root.querySelector('[data-act="refresh"]').onclick = onRefresh;
  root.querySelector('[data-act="save"]').onclick = onSave;

  _switchTab("palette");

  // Returned handle lets init.js push updates after re-scan.
  var handle = {
    _currentIssues: [],
    _currentPreview: null,
    setLint: function (issues) {
      handle._currentIssues = issues || [];
      var ec = handle._currentIssues.filter(function (i) { return i.severity === "error"; }).length;
      var wc = handle._currentIssues.filter(function (i) { return i.severity === "warning"; }).length;
      if (lintCountEl) {
        lintCountEl.textContent = ec ? (ec + " err") : (wc ? (wc + " warn") : "✓");
        lintCountEl.className = "_eli3_te_tab_count" + (ec ? " _eli3_te_tab_count_err" : (wc ? " _eli3_te_tab_count_warn" : " _eli3_te_tab_count_ok"));
      }
      if (activeTab === "lint") _renderLintList(bodyZone, handle._currentIssues);
    },
    setPreview: function (preview) {
      handle._currentPreview = preview;
      if (activeTab === "preview") _renderPreviewPanel(bodyZone, preview);
    },
    setMetadata: function (meta) {
      currentMetadata = meta || {};
      if (activeTab === "meta") _renderMetadataForm(bodyZone);
    },
    switchTab: _switchTab,
  };
  return handle;
}

jsonTools.init:
function init(eli) {
  eli = eli || window.eli;
  if (!eli || !eli.register) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded["template_editor"];
  if (!bundle) {
    try { eli.log.event("template_editor.boot_no_bundle"); } catch (_) {}
    return;
  }
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns   || {};
  var _parseTemplate      = efns.parseTemplate;
  var _lintTemplate       = efns.lintTemplate;
  var _fillTemplateSample = efns.fillTemplateSample;
  var _renderLanding      = vfns.renderTemplateEditorLanding;
  var _renderEditor       = vfns.renderTemplateEditor;
  if (!_parseTemplate || !_lintTemplate || !_renderEditor) {
    try {
      eli.log.event("template_editor.boot_missing_deps", {
        hasParse:    !!_parseTemplate,
        hasLint:     !!_lintTemplate,
        hasRenderEd: !!_renderEditor,
      });
    } catch (_) {}
    return;
  }

  // Kill switch — fleet-wide disable via admin-overrides.json
  try {
    eli.settings.register("template_editor_enabled", {
      default: true, type: "boolean", adminPushable: true,
      describe: "Template Editor tile enabled",
    });
  } catch (_) {}

  // Templates live in bd_templates (an IDB store many tools already share).
  // Metadata for editor-saved templates lives in the same store under
  // the same per-template id so Build Draft and other consumers pick
  // them up unchanged.
  var STORE_TEMPLATES = "bd_templates";

  function _loadTemplates() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll(STORE_TEMPLATES).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r === "object" && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }
  function _saveTemplateMetadata(id, meta) {
    if (!eli.storage || typeof eli.storage.get !== "function") return Promise.resolve();
    return eli.storage.get(STORE_TEMPLATES, id).then(function (existing) {
      var row = existing || { id: id };
      // Merge metadata fields onto the existing row, preserving the
      // .docx OOXML / encrypted payload that Admin Library Publisher
      // populated. Editor only edits metadata in v1; full docx replace
      // happens via the existing publish flow.
      ["name", "agreementType", "version", "description", "tags", "audienceEmails"].forEach(function (k) {
        if (meta[k] !== undefined && meta[k] !== "") row[k] = meta[k];
      });
      row.updatedAt = Date.now();
      return eli.storage.put(STORE_TEMPLATES, row);
    });
  }

  // ─── Host (Word) integration ───────────────────────────────────
  function _readDocText() {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve("");
    }
    return eli.host.runRaw("template_editor:read", function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () { return String(body.text || ""); });
    }).catch(function () { return ""; });
  }
  function _insertAtCursor(snippet) {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.reject(new Error("Word host unavailable"));
    }
    return eli.host.runRaw("template_editor:insert", function (context) {
      var sel = context.document.getSelection();
      // insertText replaces the current selection with the snippet —
      // if the cursor is collapsed (no selection), it inserts at the
      // cursor position. Both behaviors match user intent.
      try { sel.insertText(snippet, Word.InsertLocation.replace); }
      catch (_e1) {
        // Older Word builds — fall back to a paragraph-level insert.
        try { sel.insertText(snippet, "Replace"); } catch (_e2) {}
      }
      return context.sync();
    });
  }
  function _selectRange(start, length) {
    // Best-effort: find the matching text in the doc and select it,
    // so clicking a lint issue jumps the user's cursor there.
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve();
    return _readDocText().then(function (text) {
      var snippet = text.substring(start, start + Math.max(length || 2, 2));
      if (!snippet) return;
      return eli.host.runRaw("template_editor:select", function (context) {
        var body = context.document.body;
        var search = body.search(snippet, { matchCase: true, matchWholeWord: false });
        search.load("items");
        return context.sync().then(function () {
          if (search.items && search.items.length) {
            try { search.items[0].select(); } catch (_) {}
          }
          return context.sync();
        });
      }).catch(function () { /* swallow */ });
    });
  }

  // ─── State for the active editor session ───────────────────────
  var _session = null; // { templateId, name, metadata, handle }

  // ─── Landing view ──────────────────────────────────────────────
  function _openLanding() {
    try {
      if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") {
        eli.fsm.transition("scanning");
      }
    } catch (_) {}
    var mount = eli.ui && eli.ui.claimOutput
      ? eli.ui.claimOutput()
      : document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    _loadTemplates().then(function (templates) {
      _renderLanding({
        mount: mount,
        templates: templates,
        onEditCurrent: function () { _openEditor(null); },
        onEditTemplate: function (t) { _openEditor(t); },
        onBack: _goBack,
      });
      try { eli.fsm.transition("idle"); } catch (_) {}
    });
  }

  // ─── Editor view ───────────────────────────────────────────────
  function _openEditor(template) {
    try {
      if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") {
        eli.fsm.transition("scanning");
      }
    } catch (_) {}
    var mount = eli.ui && eli.ui.claimOutput
      ? eli.ui.claimOutput()
      : document.getElementById("_eli3_dashboard_root");
    if (!mount) return;

    var templateId   = template ? (template.id || template.name || "current") : "current";
    var templateName = template ? (template.name || template.label || templateId) : "Current Word Document";
    var metadata = template ? {
      name:           template.name || "",
      agreementType:  template.agreementType || "",
      version:        template.version || "",
      description:    template.description || "",
      tags:           template.tags || [],
      audienceEmails: template.audienceEmails || [],
    } : { name: templateName };

    _session = { templateId: templateId, name: templateName, metadata: metadata, handle: null };

    var handle = _renderEditor({
      mount: mount,
      templateName: templateName,
      metadata: metadata,
      onBack: _openLanding,
      onInsert: function (snippet, label) {
        _insertAtCursor(snippet).then(function () {
          try { if (typeof showToast === "function") showToast("Inserted: " + (label || snippet)); } catch (_) {}
          // Auto-refresh lint after insert
          setTimeout(_refresh, 300);
        }).catch(function (err) {
          try { if (typeof showToast === "function") showToast("Insert failed: " + (err.message || err), "error"); } catch (_) {}
        });
      },
      onRefresh: _refresh,
      onSave: function () {
        _saveTemplateMetadata(templateId, _session.metadata).then(function () {
          try { if (typeof showToast === "function") showToast("Metadata saved"); } catch (_) {}
        }).catch(function (err) {
          try { if (typeof showToast === "function") showToast("Save failed: " + (err.message || err), "error"); } catch (_) {}
        });
      },
      onLintItemClick: function (iss) {
        if (!iss) return;
        _selectRange(iss.start, (iss.end || iss.start + 2) - iss.start);
      },
      onMetadataChange: function (m) { _session.metadata = m; },
    });
    if (!handle) return;
    _session.handle = handle;
    try { eli.fsm.transition("idle"); } catch (_) {}

    // Initial scan
    _refresh();
    // Also re-scan on doc change (Office.js debounced ~500ms)
    try {
      if (eli.host && typeof eli.host.onDocChange === "function") {
        var off = eli.host.onDocChange(function () {
          if (_session) _refresh();
        });
        _session._unsubscribe = off;
      }
    } catch (_) {}
  }

  function _refresh() {
    if (!_session || !_session.handle) return;
    _readDocText().then(function (text) {
      var issues  = _lintTemplate(text) || [];
      var preview = _fillTemplateSample ? _fillTemplateSample(text, {}, "include") : null;
      _session.handle.setLint(issues);
      _session.handle.setPreview(preview);
    });
  }

  function _goBack() {
    if (_session && _session._unsubscribe) {
      try { _session._unsubscribe(); } catch (_) {}
    }
    _session = null;
    try { eli.fsm.transition("idle"); } catch (_) {}
    if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
  }

  // ─── Tile registration ─────────────────────────────────────────
  eli.register({
    tile: { app_template_editor: _openLanding },
    tile_settings: { app_template_editor: _openLanding },
    template_editor: {
      open: _openLanding,
      openCurrent: function () { _openEditor(null); },
      openById: function (tid) {
        _loadTemplates().then(function (templates) {
          var t = (templates.find && templates.find(function (x) { return x.id === tid; })) || null;
          _openEditor(t);
        });
      },
    },
  });
}

jsonTools.css:
/* template_editor — premium navy/gold palette
   Light tool view in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_te_root {
  font: 13px/1.5 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0;
  min-height: 100vh;
  box-sizing: border-box;
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._eli3_te_root),
.output-area:has(> ._eli3_te_root) {
  background: #f8fafc !important;
}

/* ── HEADER ───────────────────────────────────────────────────────── */
._eli3_te_header {
  background: linear-gradient(135deg, #020617 0%, #1e3a8a 100%);
  color: #f1f5f9;
  padding: 18px 20px 14px;
  border-bottom: 3px solid #c9a227;
}
._eli3_te_header_eyebrow {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 2.5px;
  color: #c9a227;
  margin-bottom: 6px;
}
._eli3_te_header_title {
  font: 700 22px/1.15 'Georgia', serif;
  margin: 0;
  letter-spacing: 0.3px;
}
._eli3_te_header_sub {
  font-size: 12px;
  color: #cbd5e1;
  margin-top: 4px;
  line-height: 1.4;
}
._eli3_te_header_actions {
  margin-top: 12px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* ── TABBAR ───────────────────────────────────────────────────────── */
._eli3_te_tabbar {
  display: flex;
  background: #fff;
  border-bottom: 1px solid #e2e8f0;
  padding: 0 8px;
  gap: 4px;
  position: sticky;
  top: 0;
  z-index: 5;
}
._eli3_te_tab {
  background: transparent;
  border: none;
  font: 600 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
  padding: 12px 14px;
  cursor: pointer;
  border-bottom: 3px solid transparent;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
}
._eli3_te_tab:hover {
  color: #0f172a;
  background: #f1f5f9;
}
._eli3_te_tab_active {
  color: #0f172a;
  border-bottom-color: #c9a227;
}
._eli3_te_tab_count {
  background: #e2e8f0;
  color: #475569;
  font: 700 10px/1 'Inter', sans-serif;
  padding: 3px 6px;
  border-radius: 8px;
  letter-spacing: 0;
}
._eli3_te_tab_count_ok   { background: #d1fae5; color: #047857; }
._eli3_te_tab_count_warn { background: #fef3c7; color: #92400e; }
._eli3_te_tab_count_err  { background: #fee2e2; color: #991b1b; }

/* ── BUTTONS ──────────────────────────────────────────────────────── */
._eli3_te_btn {
  font: 600 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 8px 14px;
  border-radius: 4px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}
._eli3_te_btn_gold {
  background: linear-gradient(180deg, #d4ac34 0%, #c9a227 100%);
  color: #0f172a;
  border-color: #b8901f;
  box-shadow: 0 1px 0 rgba(255,255,255,0.4) inset, 0 1px 2px rgba(0,0,0,0.15);
}
._eli3_te_btn_gold:hover {
  background: linear-gradient(180deg, #e0b939 0%, #d4ac34 100%);
  transform: translateY(-1px);
}
._eli3_te_btn_platinum {
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #0f172a;
  border-color: #cbd5e1;
}
._eli3_te_btn_platinum:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border-color: #94a3b8;
}
._eli3_te_btn_ghost {
  background: rgba(255,255,255,0.10);
  color: #cbd5e1;
  border-color: rgba(255,255,255,0.20);
}
._eli3_te_btn_ghost:hover {
  background: rgba(201,162,39,0.25);
  color: #f2d866;
  border-color: rgba(201,162,39,0.5);
}

/* ── BODY ─────────────────────────────────────────────────────────── */
._eli3_te_body {
  padding: 14px 16px;
}
._eli3_te_palette_intro {
  font-size: 11px;
  color: #64748b;
  font-style: italic;
  padding: 4px 4px 12px;
  border-bottom: 1px dashed #e2e8f0;
  margin-bottom: 12px;
}

/* ── PALETTE TAB ──────────────────────────────────────────────────── */
._eli3_te_palette_group {
  margin-bottom: 16px;
}
._eli3_te_palette_group_lbl {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.3px;
  color: #64748b;
  padding: 4px 0 8px;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 8px;
}
._eli3_te_palette_btn {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #c9a227;
  border-radius: 4px;
  padding: 10px 12px;
  margin-bottom: 6px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  font: 600 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  transition: all 0.15s;
  text-align: left;
}
._eli3_te_palette_btn:hover {
  border-color: #c9a227;
  background: linear-gradient(90deg, #fffbeb 0%, #fff 70%);
  transform: translateX(2px);
}
._eli3_te_palette_btn_lbl {
  font-family: 'JetBrains Mono', Menlo, 'Courier New', monospace;
  font-size: 11px;
  color: #0f172a;
  flex: 1;
  word-break: break-all;
}
._eli3_te_palette_btn_arrow {
  font-size: 16px;
  color: #c9a227;
  margin-left: 8px;
  font-weight: 700;
}

/* ── LINT TAB ─────────────────────────────────────────────────────── */
._eli3_te_lint_item {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 10px 12px;
  margin-bottom: 6px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_te_lint_item:hover {
  border-color: #94a3b8;
  background: #f8fafc;
}
._eli3_te_lint_error   { border-left: 4px solid #dc2626; }
._eli3_te_lint_warning { border-left: 4px solid #f59e0b; }
._eli3_te_lint_info    { border-left: 4px solid #3b82f6; }
._eli3_te_lint_icon {
  font-size: 16px;
  flex-shrink: 0;
  line-height: 1.3;
}
._eli3_te_lint_body {
  flex: 1;
}
._eli3_te_lint_msg {
  font: 600 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_te_lint_sug {
  font-size: 12px;
  color: #c9a227;
  margin-top: 4px;
  font-style: italic;
}
._eli3_te_lint_meta {
  font: 600 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #94a3b8;
  margin-top: 5px;
}

/* ── PREVIEW TAB ──────────────────────────────────────────────────── */
._eli3_te_preview_stats {
  display: flex;
  gap: 16px;
  background: #f1f5f9;
  padding: 8px 12px;
  border-radius: 4px;
  margin-bottom: 12px;
  font-size: 11px;
  color: #475569;
  flex-wrap: wrap;
}
._eli3_te_preview_stats strong {
  color: #c9a227;
  font-weight: 700;
}
._eli3_te_preview_doc {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 16px 20px;
  font: 14px/1.7 'Georgia', serif;
  color: #0f172a;
  max-height: calc(100vh - 320px);
  overflow-y: auto;
}
._eli3_te_preview_doc p {
  margin: 0 0 12px;
}
._eli3_te_preview_doc p:last-child { margin-bottom: 0; }

/* ── METADATA TAB ─────────────────────────────────────────────────── */
._eli3_te_input_lbl {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #64748b;
  margin-bottom: 4px;
  display: block;
}
._eli3_te_input {
  width: 100%;
  font: 13px/1.5 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 8px 10px;
  box-sizing: border-box;
}
._eli3_te_input:focus {
  outline: none;
  border-color: #c9a227;
  box-shadow: 0 0 0 2px rgba(201,162,39,0.2);
}

/* ── LIBRARY CARDS ────────────────────────────────────────────────── */
._eli3_te_section_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #64748b;
  padding: 4px 0 8px;
  border-bottom: 1px solid #e2e8f0;
  margin: 0 0 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
._eli3_te_count_chip {
  background: #f1f5f9;
  color: #475569;
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 10px;
  letter-spacing: 0;
}
._eli3_te_lib_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  border-radius: 4px;
  padding: 12px 14px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: all 0.15s;
}
._eli3_te_lib_card:hover {
  border-color: #94a3b8;
  border-left-color: #1565c0;
  transform: translateY(-1px);
  box-shadow: 0 2px 6px rgba(15,23,42,0.06);
}
._eli3_te_lib_icon { font-size: 24px; flex-shrink: 0; }
._eli3_te_lib_main { flex: 1; min-width: 0; }
._eli3_te_lib_name {
  font: 700 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_te_lib_meta {
  font: 600 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #94a3b8;
  margin-top: 4px;
}

/* ── EMPTY STATE ──────────────────────────────────────────────────── */
._eli3_te_empty {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 32px 20px;
  text-align: center;
  color: #94a3b8;
}
._eli3_te_empty_icon { font-size: 32px; margin-bottom: 8px; opacity: 0.5; }
._eli3_te_empty_msg { font-size: 13px; line-height: 1.5; }
._eli3_te_empty_msg strong { color: #c9a227; }
